appearances.css:
.app{padding:6px;border-radius:4px;font-size:9px;display:flex;flex-wrap:wrap;gap:4px;align-content:flex-start}
.top{flex:1 1 100%;margin:0;gap:4px;align-items:flex-end}
.top:first-child{display:grid;grid-template-columns:1.5fr .9fr 1.6fr .9fr .9fr .9fr .9fr 1fr}
.sel{font-size:7.5px;gap:1px;letter-spacing:0;flex-direction:column-reverse;align-items:center;text-align:center;min-width:0}
.sel span{white-space:nowrap}
select,button{font-size:9px;padding:3px 4px;border-radius:3px}
.sel select{width:100%;padding:3px 0;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none}
.stt{font-size:8px;margin:0}
h3{display:none}
.grid{display:grid;gap:2px 3px;border:1px solid var(--line,#344953);border-radius:4px;padding:4px 4px 3px;margin:0}
.grid:nth-child(5){flex:5 1 285px;grid-template-columns:repeat(5,minmax(0,1fr))}
.grid:nth-child(7){flex:2 1 114px;grid-template-columns:repeat(2,minmax(0,1fr))}
.grid:nth-child(9){flex:3 1 171px;grid-template-columns:repeat(3,minmax(0,1fr))}
.grid:nth-child(11){flex:5 1 285px;grid-template-columns:repeat(5,minmax(0,1fr))}
.c{align-items:center;gap:0}
.c .lab{display:contents}
.c .lab span{order:3;text-transform:none;font-size:7.5px;text-align:center;white-space:normal;line-height:1.1;letter-spacing:-.02em;overflow:visible}
.c .lab output{order:2;font-size:8px;line-height:1.1}
.c>.kn{order:1;width:26px!important;height:26px!important;justify-self:center}
.c .kn svg{width:100%;height:100%}
